from collections import deque

def wordLadderLength(beginWord, endWord, wordList):
    # Convert wordList to a set for O(1) lookups
    wordSet = set(wordList)

    # If endWord is not in the wordList, return 0
    if endWord not in wordSet:
        return 0

    # Initialize the queue for BFS and the visited set
    queue = deque([(beginWord, 1)])
    visited = set([beginWord])

    # Build the neighbors dictionary
    neighbors = {}
    for word in wordList:
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                neighbor = word[:i] + c + word[i+1:]
                if neighbor != word and neighbor in wordSet:
                    if neighbor not in neighbors:
                        neighbors[neighbor] = []
                    neighbors[neighbor].append(word)

    # Perform BFS
    while queue:
        current_word, level = queue.popleft()

        # Check if the current word is the endWord
        if current_word == endWord:
            return level

        # Explore neighbors
        for neighbor in neighbors.get(current_word, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, level + 1))

    # If no transformation is found, return 0
    return 0

